<style>/* Footer Bottom Border */
        .footer-bottom {
            position: relative;
            width: 100%;
            height: 48px;
            background: #f5f5f5;
            overflow: hidden;
        }

        /* The main blue background block */
        .footer-blue-bg {
            position: absolute;
            top: 0;
            bottom: 0;
            left: -100px;
            /* Extend past left edge to cover skew gap */
            right: 58px;
            /* Position where the main blue block ends */
            background: #1d2b5c;
            /* Deep navy blue matching the image */
            transform: skewX(-35deg);
            transform-origin: top;
            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.5s ease;
            animation: slideInBg 1.2s cubic-bezier(0.16, 1, 0.3, 1) both;
        }

        /* The parallel blue stripes */
        .footer-stripe {
            position: absolute;
            top: 0;
            bottom: 0;
            width: 6px;
            /* Width of the diagonal stripes */
            background: #1d2b5c;
            transform: skewX(-35deg);
            transform-origin: top;
            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.5s ease, filter 0.5s ease;
        }

        .footer-stripe-1 {
            right: 44px;
            animation: slideInStripe 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.4s both;
        }

        .footer-stripe-2 {
            right: 30px;
            animation: slideInStripe 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.6s both;
        }

        /* Interactive Hover Effects */
        .footer-bottom:hover .footer-blue-bg {
            background-color: #2b3d80; /* Brighter/richer blue on hover */
            transform: skewX(-35deg) scaleX(1.01);
        }

        .footer-bottom:hover .footer-stripe {
            background-color: #2b3d80;
            filter: drop-shadow(0 0 4px rgba(43, 61, 128, 0.6));
        }

        .footer-bottom:hover .footer-stripe-1 {
            transform: skewX(-35deg) translateX(4px);
        }

        .footer-bottom:hover .footer-stripe-2 {
            transform: skewX(-35deg) translateX(8px);
        }

        /* Animations */
        @keyframes slideInBg {
            from {
                transform: skewX(-35deg) translateX(-100%);
            }
            to {
                transform: skewX(-35deg) translateX(0);
            }
        }

        @keyframes slideInStripe {
            from {
                transform: skewX(-35deg) translateX(50px);
                opacity: 0;
            }
            to {
                transform: skewX(-35deg) translateX(0);
                opacity: 1;
            }
        }

        /* Responsive adjustments */
        @media (max-width: 768px) {
            .footer-bottom {
                height: 40px;
            }

            .footer-blue-bg {
                right: 42px;
            }

            .footer-stripe {
                width: 4.5px;
            }

            .footer-stripe-1 {
                right: 32px;
            }

            .footer-stripe-2 {
                right: 22px;
            }
        }</style>","originalElement":"__raw_html__"}],"baseStyles":{"backgroundColor":"#f5f5f5","display":"flex","flexDirection":"column","gap":"40px","margin":"0 auto","maxWidth":"100%","paddingBottom":"0px","paddingLeft":"0px","paddingRight":"0px","paddingTop":"60px","position":"static","width":"100%"},"mobileStyles":{"padding":"30px 0px 0px"},"tabletStyles":{"paddingBottom":"45px","paddingTop":"45px"},"blockName":"Footer Section","element":"div","isRepeaterBlock":false}
